// reproducible-example.js
import chromeLauncher from 'chrome-launcher';
import lighthouse from 'lighthouse';

(async () => {
  // 1) Launch a headless Chrome
  const chrome = await chromeLauncher.launch({ chromeFlags: ['--headless'] });
  const options = {
    port: chrome.port,
    // We're not passing any special flags here.
  };

  // 2) Create a custom Lighthouse config that omits any trace gatherers
  //    and only includes two simple artifacts. As a result, the
  //    performance audits have no trace data to operate on.
  const config = {
    // Do not extend the default, build config from scratch
    extends: null,

    // Minimal artifacts: URL and viewport (no trace artifacts)
    artifacts: [
      { id: 'URL', gatherer: 'url' },
      { id: 'ViewportDimensions', gatherer: 'viewport-dimensions' }
    ],

    // Tell Lighthouse exactly which audits and categories to run
    audits: [
      'first-contentful-paint',
      'first-meaningful-paint',
      'speed-index',
      'interactive',
      'max-potential-fid',
      // also include a couple of opportunities / diagnostics
      'offscreen-images',
      'unused-css-rules'
    ],

    categories: {
      performance: {
        title: 'Performance',
        description: 'Performance metrics',
        auditRefs: [
          { id: 'first-contentful-paint', weight: 1 },
          { id: 'first-meaningful-paint', weight: 1 },
          { id: 'speed-index', weight: 1 },
          { id: 'interactive', weight: 1 },
          { id: 'max-potential-fid', weight: 1 },
          { id: 'offscreen-images', weight: 0 },
          { id: 'unused-css-rules', weight: 0 }
        ]
      }
    }
  };

  // 3) Run Lighthouse with the broken config
  const { lhr } = await lighthouse('https://www.cnn.com', options, config);

  // 4) Output the runtimeError and the report HTML for inspection
  console.log('Top‐level runtimeError:', lhr.runtimeError || 'none');

  // Write the full HTML report so you can open it and see the red “Error” badges:
  require('fs').writeFileSync('broken-report.html', lhr.report, 'utf-8');

  // 5) Clean up
  await chrome.kill();
})();
